const SCRIPT = "(function(){\n  var views={start:START_HTML,findings:FINDINGS_HTML};\n  var stage=document.getElementById('stage'), wrap=document.getElementById('wrap'), cur='start';\n  function post(m){try{parent.postMessage(m,'*');}catch(e){}}\n  function fit(){\n    var art=stage.firstElementChild; if(!art) return;\n    var w=wrap.clientWidth||document.documentElement.clientWidth||1600;\n    var s=Math.min(1,w/1600);\n    stage.style.transform='scale('+s+')';\n    var h=art.offsetHeight*s;\n    wrap.style.height=h+'px';\n    post({jsonrpc:'2.0',method:'ui/notifications/size-changed',params:{height:Math.ceil(document.documentElement.scrollHeight)}});\n  }\n  function show(v){\n    cur=v; stage.innerHTML=views[v];\n    var art=stage.firstElementChild; if(art){art.style.height='auto';art.style.minHeight='0';}\n    var all=stage.querySelectorAll('div,section,aside,p');for(var i=0;i<all.length;i++){var t=all[i].textContent.trim();if(t.indexOf('DESIGN NOTE')===0&&t.length<600)all[i].style.display='none';}\n    wire(); setTimeout(fit,0);\n  }\n  function byText(t){var out=[],all=stage.querySelectorAll('span,button,a,div');for(var i=0;i<all.length;i++){var el=all[i];if(el.children.length<=2&&el.textContent.trim()===t)out.push(el);}return out;}\n  function clickable(els,fn){els.forEach(function(el){el.style.cursor='pointer';el.addEventListener('click',fn);});}\n  function wire(){\n    if(cur==='start'){clickable(byText('Run the check'),function(){show('findings');});}\n    else{\n      ['Your lot','Your project','Your plans'].forEach(function(t){\n        var els=stage.querySelectorAll('span');for(var i=0;i<els.length;i++){if(els[i].textContent.replace(/✓/g,'').trim()===t)clickable([els[i]],function(){show('start');});}\n      });\n    }\n  }\n  window.addEventListener('message',function(ev){var d=ev.data;if(d&&d.id===0&&d.result)post({jsonrpc:'2.0',method:'ui/notifications/initialized'});});\n  window.addEventListener('resize',fit);\n  var ex=document.getElementById('expand');ex.addEventListener('click',function(){post({jsonrpc:'2.0',id:7,method:'ui/request-display-mode',params:{mode:'fullscreen'}});setTimeout(fit,300);});\n  window.addEventListener('message',function(ev){var d=ev.data;if(d&&d.method==='ui/notifications/host-context-changed'){setTimeout(fit,50);}});\n  post({jsonrpc:'2.0',id:0,method:'ui/initialize',params:{protocolVersion:'2026-01-26',appInfo:{name:'PlanReviewPrecheck',version:'3'},appCapabilities:{availableDisplayModes:['inline','fullscreen']}}});\n  show('start');\n})();";

export function buildPlanReviewPreviewPage(): string {
  const script = SCRIPT.replace("START_HTML", JSON.stringify(START).replace(/</g, "\\u003c")).replace("FINDINGS_HTML", JSON.stringify(FINDINGS).replace(/</g, "\\u003c"));
  return (
    '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Plan precheck</title><style>' +
    STYLE +
    "html,body{margin:0;background:var(--sc-canvas);}#wrap{width:100%;overflow:hidden;position:relative}#stage{width:1600px;transform-origin:0 0;position:absolute;left:0;top:0}#expand{position:fixed;bottom:8px;right:8px;z-index:5;font:600 12px/1 system-ui,sans-serif;padding:7px 10px;border-radius:6px;border:1px solid #AEBAC5;background:#fff;color:#101820;cursor:pointer;box-shadow:0 1px 3px rgba(0,0,0,.15)}" +
    '</style></head><body><button id="expand" title="Open full screen">Expand ⤢</button><div id="wrap"><div id="stage"></div></div><script>' +
    script +
    "</script></body></html>"
  );
}
